 static Material Mat(string n,Color color,string texture=null){var path=E+"Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name=n;m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",.16f);m.SetFloat("_SpecularHighlights",0);m.SetFloat("_Cull",2);m.DisableKeyword("_EMISSION");m.SetColor("_EmissionColor",Color.black);m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.EmissiveIsBlack;if(texture!=null){m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+texture+".png"));m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.35f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}else m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/CW_Paint_Base.png"));EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
 static void Assign(Renderer r,Material m){r.sharedMaterial=m;changedRenderers.Add(PathOf(r.transform));}
 static void Marker(Geo g,Vector3 p,Vector3 f,string type){var r=Vector3.Cross(Vector3.up,f).normalized;if(type=="circle"){for(int i=0;i<24;i++){float a=i*Mathf.PI*2/24,b=(i+1)*Mathf.PI*2/24;g.Quad(p+(r*Mathf.Cos(a)+f*Mathf.Sin(a))*.065f,p+(r*Mathf.Cos(a)+f*Mathf.Sin(a))*.09f,p+(r*Mathf.Cos(b)+f*Mathf.Sin(b))*.065f,p+(r*Mathf.Cos(b)+f*Mathf.Sin(b))*.09f);}}else if(type=="double"){foreach(float x in new[]{-.07f,.07f})g.Rect(p+r*x,f,.026f,.24f);}else{var pts=type=="diamond"?new[]{p+f*.09f,p+r*.09f,p-f*.09f,p-r*.09f}:new[]{p-r*.075f-f*.075f,p+r*.075f-f*.075f,p+r*.075f+f*.075f,p-r*.075f+f*.075f};for(int i=0;i<4;i++)g.Stroke(pts[i],pts[(i+1)%4],.025f);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 Edit scene required");root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/T02_StairA/plan.json"));labFloor=root.Find("C01_Experiment_Art/S1_FloorFinish_02").GetComponent<Renderer>().bounds.max.y;paints.Clear();labels.Clear();changedRenderers.Clear();Physics.SyncTransforms();
 foreach(var f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Environment/B5/Textures"),"ND_*.png")){var path=E+"Textures/"+Path.GetFileName(f);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.alphaIsTransparency=true;ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.filterMode=FilterMode.Trilinear;ti.wrapMode=TextureWrapMode.Clamp;ti.SaveAndReimport();}
 foreach(var entry in (JObject)plan["destinations"]){Color col;ColorUtility.TryParseHtmlString((string)entry.Value["color"],out col);paints[entry.Key]=Mat("ND_Paint_"+entry.Key,col);labels[entry.Key]=Mat("ND_Label_"+entry.Key,col,"ND_Floor_"+entry.Key);}
 var old=root.Find("Destination_Colour_Guidance");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var parent=new GameObject("Destination_Colour_Guidance");parent.transform.SetParent(root,false);parent.transform.position=Vector3.zero;group=parent.transform;Undo.RegisterCreatedObjectUndo(parent,"Destination colour wayfinding");
 foreach(var route in plan["routes"]){var ps=route["points"].Select(V).ToArray();string code=(string)route["code"];var g=new Geo();g.Ribbon(ps,.10f);float total=0,nextArrow=2.2f,nextSymbol=4.2f;for(int i=1;i<ps.Length;i++){float len=Vector3.Distance(ps[i-1],ps[i]);if(len<.00001f)continue;var f=(ps[i]-ps[i-1])/len;var r=Vector3.Cross(Vector3.up,f);while(nextArrow<=total+len){var at=Vector3.Lerp(ps[i-1],ps[i],(nextArrow-total)/len);g.Stroke(at-f*.14f-r*.075f,at+f*.14f,.025f);g.Stroke(at-f*.14f+r*.075f,at+f*.14f,.025f);nextArrow+=3.5f;}while(nextSymbol<=total+len){var at=Vector3.Lerp(ps[i-1],ps[i],(nextSymbol-total)/len);Marker(g,at,f,(string)plan["destinations"][code]["pattern"]);nextSymbol+=6.5f;}total+=len;}Add("ND_"+(string)route["id"],g,paints[code]);}
 // Retain original assets while replacing their scene renderers with the new network.
 foreach(var rr in root.Find("Facility_Floor_Guidance_R1").GetComponentsInChildren<Renderer>()){rr.enabled=false;changedRenderers.Add(PathOf(rr.transform));}var c02=root.Find("C02_Security_Art");var branch=c02.Find("SC_R1_T05_ToC04").GetComponent<Renderer>();branch.enabled=false;changedRenderers.Add(PathOf(branch.transform));
 var workplace=root.Find("C01_Experiment_Art/C01_Workplace_Wayfinding");workplace.Find("CW_R1_FloorRoute").GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/CW_Paint_R1.mat");workplace.Find("CW_R1_FloorCodes").GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/CW_FloorCode_R1.mat");
 // Join the old two painted strips to the single C01 destination lane without changing the old mesh.
 var cw=workplace.Find("CW_R1_FloorRoute").GetComponent<MeshFilter>();var vv=cw.sharedMesh.vertices;int mid=vv.Length/2;var ends=new[]{vv[mid-2],vv[mid-1],vv[vv.Length-2],vv[vv.Length-1]}.Select(v=>cw.transform.TransformPoint(v)).ToArray();var cyan=plan["routes"].Single(r=>(string)r["id"]=="C01_FromVA")["points"].Select(V).ToArray();var tip=cyan.Last();var forward=(cyan[cyan.Length-2]-tip).normalized;var right=Vector3.Cross(Vector3.up,forward);var sorted=ends.OrderBy(v=>Vector3.Dot(v,right)).ToArray();var cap=new Geo();cap.Quad(sorted.First(),sorted.Last(),tip+forward*.18f-right*.05f,tip+forward*.18f+right*.05f);Add("ND_C01_LocalJoin",cap,paints["C01"]);
 foreach(var rr in root.Find("T01_Corridor_Finish").GetComponentsInChildren<Renderer>().Where(r=>r.name.StartsWith("T01_C"))){string code=rr.name.Contains("C01")?"C01":"C02";Assign(rr,labels[code]);}foreach(string code in new[]{"C01","VA"})Assign(c02.Find("SC_Destination_"+code).GetComponent<Renderer>(),labels[code]);
 c02.Find("SC_Destination_VA").GetComponent<Renderer>().enabled=true;
 var core=plan["coreLegend"];var coreGeo=new Geo();coreGeo.Rect(V(core["position"]),Vector3.forward,(float)core["width"],(float)core["length"]);Add("ND_Core_Destinations",coreGeo,Mat("ND_Legend_VA",Color.white,"ND_Legend_VA"));
 var legend=plan["legend"];var lg=new Geo();lg.Rect(V(legend["position"]),new Vector3((float)legend["forward"][0],0,(float)legend["forward"][1]),(float)legend["width"],(float)legend["length"]);Add("ND_Floor_Destinations",lg,Mat("ND_Legend",Color.white,"ND_Legend"));
 var lab=plan["labLegend"];var lgeo=new Geo();lgeo.Rect(V(lab["position"]),Vector3.forward,(float)lab["width"],(float)lab["length"]);Add("ND_Lab_Destinations",lgeo,Mat("ND_Legend_C01",Color.white,"ND_Legend_C01"));
 AssetDatabase.DeleteAsset(E+"Materials/ND_LocalCode_C01.mat");AssetDatabase.DeleteAsset(E+"Textures/ND_Code_C01.png");
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{scene=s.path,routes=plan["routes"].Count(),destinations=3,newMeshCount=group.GetComponentsInChildren<MeshFilter>().Length,newColliders=group.GetComponentsInChildren<Collider>().Length,newBehaviours=group.GetComponentsInChildren<MonoBehaviour>().Length,newLights=group.GetComponentsInChildren<Light>().Length,changedRenderers,allLights=root.GetComponentsInChildren<Light>(true).Length};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_T02_StairA/guide_apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
